// Frequency-prioritized, diversified three-word seed receiver.
// Candidate search is heuristic; full action verification remains exact.
// No original exclusion from a failed or truncated search.
#include <bits/stdc++.h>
#include <immintrin.h>
#pragma GCC target("avx2")
#include <omp.h>
#define omp_set_num_threads(x) ((void)0)
#include "lp2_q13_common_cycle_affine_core.hpp"
#undef omp_set_num_threads
#include <codecvt>
#include <locale>
#include <random>
#include <regex>
#include <set>
#include <sstream>
