using namespace std;
static string file(const string& p){ifstream f(p);if(!f)throw runtime_error(p);return string(istreambuf_iterator<char>(f),{});}
static vector<string> words(const string& s){istringstream f(s);vector<string> v;string w;while(f>>w)v.push_back(w);return v;}
static string jsonfield(const string&s,const string&key){regex re("\""+key+"\"\\s*:\\s*\"([^\"]*)\"");smatch m;if(!regex_search(s,m,re))throw runtime_error(key);return m[1];}
static vector<string> jsonfields(const string&s,const string&key){regex re("\""+key+"\"\\s*:\\s*\"([^\"]*)\"");vector<string> out;for(sregex_iterator it(s.begin(),s.end(),re),e;it!=e;++it)out.push_back((*it)[1]);return out;}
static set<string> D;
static unordered_map<string,double> freq;
static double currentFreq=0;
static double weight(const string&w){auto i=freq.find(w);return i==freq.end()?0:i->second;}
static vector<string> by[64];
static const vector<string> runeNames={"F","U","TH","O","R","C","G","W","H","N","I","J","EO","P","X","S","T","B","E","M","L","NG","OE","D","A","AE","Y","IA","EA"};
static void spelling(const string&s,int i,string w){if(i==(int)s.size()){D.insert(w);freq[w]+=currentFreq;return;}for(int n=1;n<=3&&i+n<=(int)s.size();n++){string t=s.substr(i,n);int j=-1;if(n==3){if(t=="ING")j=21;}else for(int q=0;q<29;q++)if(t==runeNames[q]){j=q;break;}if(j>=0)spelling(s,i+n,w+alphabet[j]);}}
static void loadD(){istringstream in(file("resources/control/english_wordfreq_textblob.txt"));string line;regex re("^([a-z]+)\\s+([0-9]+)$");smatch m;while(getline(in,line)){if(!regex_match(line,m,re))continue;currentFreq=stod(m[2]);string s=m[1],v;for(char c:s)v+=toupper(c);string z;for(int i=0;i<(int)v.size();i++){if(v.substr(i,2)=="QU"){z+="CW";i++;continue;}char c=v[i];z+=c=='V'?'U':c=='K'||c=='Q'?'C':c=='Z'?'S':c;}spelling(z,0,"");}if(D.size()!=38910)throw runtime_error("base dictionary "+to_string(D.size()));for(auto w:words(jsonfield(file("im-results/lp2-shared-gp29-q8-terminal-corrected-fixtures.json"),"added")))D.insert(w);if(D.size()!=38938)throw runtime_error("dictionary size");for(auto&w:D)if(w.size()<64)by[w.size()].push_back(w);}
static bool localok(const string&w,const string&c){array<int,377> m,r;m.fill(-1);r.fill(-1);array<int,13> same;same.fill(-1);int j=0;for(int i=0;i<(int)w.size();i++){int p=alphabet.find(w[i]),x=alphabet.find(c[i]);if(!p){if(x)return false;continue;}if((m[29*j+p]>=0&&m[29*j+p]!=x)||(r[29*j+x]>=0&&r[29*j+x]!=p)||(same[j]>=0&&same[j]!=(p==x)))return false;m[29*j+p]=x;r[29*j+x]=p;same[j]=p==x;j=(j+1)%13;}return true;}
static void mkgroup(const vector<string>&C){groups.clear();groups.resize(C.size());for(int i=0;i<(int)C.size();i++){auto&g=groups[i];g.cipher=C[i];for(auto&w:by[C[i].size()])if(localok(w,C[i])){Option op;op.word=w;int j=0;for(int b=0;b<(int)w.size();b++){int c=alphabet.find(C[i][b]),p=alphabet.find(w[b]);if(!p)continue;op.e.push_back({u8(c),u8(p),u8(j)});j=(j+1)%13;}g.opts.push_back(move(op));}build_masks(g);}order.resize(C.size());iota(order.begin(),order.end(),0);sort(order.begin(),order.end(),[](int a,int b){auto score=[](int g){return log2(double(max<size_t>(1,groups[g].opts.size())))/max(1,(int)groups[g].cipher.size()-(int)count(groups[g].cipher.begin(),groups[g].cipher.end(),'0'));};return score(a)!=score(b)?score(a)<score(b):a<b;});}
static string encrypt(const string&w,const vector<int>&p,const vector<int>&k,int j){vector<int> invp(29);for(int i=0;i<29;i++)invp[p[i]]=i;string c;for(char a:w){int x=alphabet.find(a);if(!x)c+='0';else{c+=alphabet[invp[md(p[x]+k[j])]];j=(j+1)%13;}}return c;}
static set<string> dec(const string&c,const vector<int>&p,const vector<int>&k){vector<int> invp(29);for(int i=0;i<29;i++)invp[p[i]]=i;set<string> out;string w;function<void(int,int,int)> rec=[&](int i,int j,int start){if(i==(int)c.size()){if(D.count(w)){if(encrypt(w,p,k,start)!=c)throw runtime_error("forward replay");out.insert(w);}return;}int x=alphabet.find(c[i]);if(!x){w+='0';rec(i+1,j,start);w.pop_back();}int y=invp[md(p[x]-k[j])];if(y){w+=alphabet[y];rec(i+1,(j+1)%13,start);w.pop_back();}};for(int j=0;j<13;j++)rec(0,j,j);return out;}
static void force(const State&st,const vector<int>&seed,int i,const vector<int>&rem,Count&cnt){if(timeout())return;if(st.d<=2){complete(st);return;}if(i==(int)seed.size()){dfs(st,i,cnt,rem,maxOOV);return;}Filter f(st);auto dd=domain(groups[seed[i]],f,numeric_limits<size_t>::max());stable_sort(dd.entries.begin(),dd.entries.end(),[&](auto a,auto b){return weight(groups[seed[i]].opts[a.first].word)>weight(groups[seed[i]].opts[b.first].word);});if(dd.entries.size()>512)dd.entries.resize(512);for(auto [o,j]:dd.entries){if(timeout())return;cnt.ext++;State n=st;if(extend(n,groups[seed[i]].opts[o],j))force(n,seed,i+1,rem,cnt);}}
static string arr(const vector<int>&v){string s="[";for(int i=0;i<(int)v.size();i++){if(i)s+=",";s+=to_string(v[i]);}return s+"]";}
struct Recovery{vector<int> p,k;vector<string> stats;};
static Recovery recover(const vector<string>&C,int secs,int nthreads){mkgroup(C);maxOOV=6;Recovery out;vector<vector<int>> seeds,all;int n=min(16,(int)order.size());for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)for(int k=j+1;k<n;k++)all.push_back({order[i],order[j],order[k]});auto score=[](const vector<int>&s){double z=0;for(int i:s)z+=log2(double(max<size_t>(1,groups[i].opts.size())))-0.7*groups[i].cipher.size();return z;};stable_sort(all.begin(),all.end(),[&](const auto&a,const auto&b){return score(a)<score(b);});for(int i=0;i<min(12,(int)all.size());i++)seeds.push_back(all[i]);mt19937 chooser(0x29fa77a1u);shuffle(all.begin()+min(12,(int)all.size()),all.end(),chooser);for(int i=12;i<min(40,(int)all.size());i++)seeds.push_back(all[i]);
for(auto&seed:seeds){if(found)break;stopFlag=false;globalNodes=globalExtends=globalFilter=globalEnum=globalResidual=0;vector<int> rem;for(int i:order)if(find(seed.begin(),seed.end(),i)==seed.end())rem.push_back(i);auto&anchor=groups[seed[0]];vector<int> roots(anchor.opts.size());iota(roots.begin(),roots.end(),0);stable_sort(roots.begin(),roots.end(),[&](int a,int b){return weight(anchor.opts[a].word)>weight(anchor.opts[b].word);});if(roots.size()>96)roots.resize(96);startTime=chrono::steady_clock::now();endTime=startTime+chrono::seconds(secs);atomic<int> next{0},finished{0};ostringstream capture;auto*old=cout.rdbuf(capture.rdbuf());vector<thread> pool;for(int t=0;t<nthreads;t++)pool.emplace_back([&](){while(!timeout()){int i=next++;if(i>=(int)roots.size())break;Count cnt;State st;if(extend(st,anchor.opts[roots[i]],0))force(st,seed,1,rem,cnt);flushCount(cnt);if(!stopFlag)finished++;}});for(auto&t:pool)t.join();cout.rdbuf(old);string log=capture.str();bool timed=!found&&chrono::steady_clock::now()>endTime;ostringstream os;os<<"{\"seed\":"<<arr(seed)<<",\"done\":"<<finished<<",\"total\":"<<roots.size()<<",\"nodes\":"<<globalNodes<<",\"extends\":"<<globalExtends<<",\"enum\":"<<globalEnum<<",\"residual\":"<<globalResidual<<",\"timed\":"<<(timed?"true":"false")<<",\"seconds\":"<<elapsed()<<"}";out.stats.push_back(os.str());cout<<os.str()<<endl;if(found){cout<<log;smatch m;regex pr("KEY pi ([^\\n]+)"),kr("KEY k ([^\\n]+)");if(!regex_search(log,m,pr))throw runtime_error("missing pi");for(auto&x:words(m[1]))out.p.push_back(stoi(x));if(!regex_search(log,m,kr))throw runtime_error("missing k");for(auto&x:words(m[1]))out.k.push_back(stoi(x));break;}}
return out;}
static vector<string> originalChapter(){wstring_convert<codecvt_utf8<char32_t>,char32_t> cv;auto s=cv.from_bytes(file("resources/transcriptions/lp2-image-corrected.txt"));u32string r=U"ᚠᚢᚦᚩᚱᚳᚷᚹᚻᚾᛁᛄᛇᛈᛉᛋᛏᛒᛖᛗᛚᛝᛟᛞᚪᚫᚣᛡᛠ";int pg=0;vector<string> v;string w;for(char32_t c:s){if(c==U'%'){pg++;continue;}if(pg<40||pg>=53)continue;if(c==U'/'||c==U'\n'||c==U'\r'||c==U' '||c==U'\t')continue;size_t i=r.find(c);if(i!=u32string::npos)w+=alphabet[i];else if(!w.empty()){v.push_back(w);w.clear();}}if(!w.empty())v.push_back(w);int n=0;for(auto&x:v)n+=x.size();if(v.size()!=669||n!=3008)throw runtime_error("chapter shape "+to_string(v.size())+"/"+to_string(n));return v;}
int main(int argc,char**argv){for(int i=0;i<29;i++)for(int j=0;j<29;j++){mult[i][j]=i*j%29;if(i*j%29==1)inv[i]=j;}loadD();string mode=argc>1?argv[1]:"0";int secs=argc>2?stoi(argv[2]):60;int threads=argc>3?stoi(argv[3]):2;string f=file("im-results/lp2-shared-gp29-q8-affine-long-fixtures.json");auto original=words(jsonfield(f,"originalTrain"));vector<string>C=original,H,T,HT;vector<int>p,k,omitted;bool control=mode!="original";
if(control){int i=stoi(mode);if(i<0||i>3)throw runtime_error("plant index");auto truths=jsonfields(f,"truth");auto t=words(truths[i%2]);if(t.size()!=64)throw runtime_error("plant size");T.assign(t.begin(),t.begin()+24);HT.assign(t.begin()+24,t.end());mt19937 rng(0x29fa1300u+i);p.resize(29);iota(p.begin(),p.end(),0);shuffle(p.begin()+2,p.end(),rng);for(int q=0;q<13;q++)k.push_back(rng()%29);if(all_of(k.begin(),k.end(),[&](int x){return x==k[0];}))k[12]=(k[12]+1)%29;if(i<2){for(int q=0;q<6;q++)omitted.push_back(q+7*(q%3));}else{vector<int> choice(24);iota(choice.begin(),choice.end(),0);shuffle(choice.begin(),choice.end(),rng);omitted.assign(choice.begin(),choice.begin()+6);sort(omitted.begin(),omitted.end());}for(int q=0;q<24;q++){if(find(omitted.begin(),omitted.end(),q)!=omitted.end()){do{T[q].clear();for(int j=0;j<(int)original[q].size();j++)T[q]+=alphabet[1+rng()%28];C[q]=encrypt(T[q],p,k,rng()%13);}while(!dec(C[q],p,k).empty());}else{if(!D.count(T[q]))throw runtime_error("donor OOV");C[q]=encrypt(T[q],p,k,rng()%13);}}for(auto&w:HT)H.push_back(encrypt(w,p,k,rng()%13));}
else{auto v=originalChapter();vector<string>L;for(auto&w:v)(w.size()>=10?L:H).push_back(w);auto t=original;sort(t.begin(),t.end());sort(L.begin(),L.end());if(t!=L)throw runtime_error("long anchors changed");}
auto R=recover(C,secs,threads);int train=0,held=0,trueTrain=0,trueHeld=0;bool exact=false;if(!R.p.empty()){for(int i=0;i<24;i++){auto d=dec(C[i],R.p,R.k);train+=!d.empty();if(control)trueTrain+=d.count(T[i]);}for(int i=0;i<(int)H.size();i++){auto d=dec(H[i],R.p,R.k);held+=!d.empty();if(control)trueHeld+=d.count(HT[i]);}if(control&&R.p==p)for(int j=0;j<13;j++){bool same=true;for(int q=0;q<13;q++)same&=R.k[q]==k[(q+j)%13];exact|=same;}}
ostringstream os;os<<"{\"heuristic\":true,\"q\":13,\"mode\":\""<<mode<<"\",\"budget\":6,\"dictionary\":"<<D.size()<<",\"found\":"<<(!R.p.empty()?"true":"false")<<",\"exact\":"<<(exact?"true":"false")<<",\"train_supported\":"<<train<<",\"train_truth\":"<<trueTrain<<",\"holdout_supported\":"<<held<<",\"holdout_truth\":"<<trueHeld<<",\"holdout_count\":"<<H.size()<<",\"omitted\":"<<arr(omitted)<<",\"pi\":"<<arr(R.p)<<",\"key\":"<<arr(R.k)<<",\"seeds\":[";for(int i=0;i<(int)R.stats.size();i++){if(i)os<<",";os<<R.stats[i];}os<<"]}";cout<<"FINAL "<<os.str()<<endl;if(const char*path=getenv("SFT_OUTPUT")){ofstream out(path);out<<os.str()<<endl;}return 0;}
